<body>
<canvas id="game" width="224" height="288"></canvas>
<script>
/*
  Galaga clone in one file.

  Internal resolution: 224 x 288, arcade-like 3:4 portrait.
  Everything is drawn with canvas primitives and pre-rendered pixel sprites.
  Audio is synthesized with Web Audio.
*/

"use strict";

/* ------------------------------------------------------------------ */
/* Canvas and scaling                                                 */
/* ------------------------------------------------------------------ */

const W = 224;
const H = 288;

const canvas = document.getElementById("game");
const ctx = canvas.getContext("2d");
ctx.imageSmoothingEnabled = false;

function resizeCanvas() {
  const scale = Math.max(1, Math.floor(Math.min(window.innerWidth / W, window.innerHeight / H)));
  canvas.style.width = (W * scale) + "px";
  canvas.style.height = (H * scale) + "px";
}
window.addEventListener("resize", resizeCanvas);
resizeCanvas();

/* ------------------------------------------------------------------ */
/* Small helpers                                                      */
/* ------------------------------------------------------------------ */

const STEP = 1 / 60;

function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function lerp(a, b, t) { return a + (b - a) * t; }
function rand(a, b) { return a + Math.random() * (b - a); }
function randInt(a, b) { return Math.floor(rand(a, b + 1)); }
function dist2(x1, y1, x2, y2) { const dx = x1 - x2, dy = y1 - y2; return dx * dx + dy * dy; }

function rectOverlap(ax, ay, aw, ah, bx, by, bw, bh) {
  return ax < bx + bw && ax + aw > bx && ay < by + bh && ay + ah > by;
}

/* ------------------------------------------------------------------ */
/* Pixel sprites                                                      */
/* ------------------------------------------------------------------ */

const PALETTE = {
  "1": "#ffffff",
  "2": "#2255ff",
  "3": "#ffcc00",
  "4": "#ff3333",
  "5": "#22cc22",
  "6": "#9933ff",
  "7": "#33ffff"
};

const PLAYER_ROWS = [
  "......1......",
  ".....111.....",
  ".....111.....",
  "....11111....",
  "....11111....",
  "...1111111...",
  "...1111111...",
  "..111111111..",
  "..111111111..",
  ".11111111111.",
  ".11111111111.",
  "1111111111111",
  "1111111111111"
];

const ZAKO_0 = [
  ".....222.....",
  "....22222....",
  "...2222222...",
  "..222222222..",
  ".33322222333.",
  ".33322222333.",
  ".33322222333.",
  ".33322222333.",
  ".33322222333.",
  "..222222222..",
  "...2222222...",
  "....22222....",
  ".....222....."
];

const ZAKO_1 = [
  ".....222.....",
  "....22222....",
  "...2222222...",
  "..222222222..",
  ".33222222233.",
  ".33222222233.",
  ".33222222233.",
  ".33222222233.",
  ".33222222233.",
  "..222222222..",
  "...2222222...",
  "....22222....",
  ".....222....."
];

const GOEI_0 = [
  ".....444.....",
  "....44444....",
  "...4444444...",
  "..444444444..",
  ".44444444444.",
  ".44444444444.",
  ".44444444444.",
  ".44444444444.",
  ".44444444444.",
  "..444444444..",
  "...4444444...",
  "....44444....",
  ".....444....."
];

const GOEI_1 = [
  ".....444.....",
  "....44444....",
  "...4444444...",
  "..444444444..",
  "..444444444..",
  "..444444444..",
  "..444444444..",
  "..444444444..",
  "..444444444..",
  "..444444444..",
  "...4444444...",
  "....44444....",
